const results = await Promise.allSettled([
  tools.exec_command({cmd:"find .. -name AGENTS.md -print","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"ls -la .entire && cat .entire/.gitignore && find .entire -maxdepth 3 -type f -print","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"find . -maxdepth 3 -type f -not -path './.git/*' -print","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"python3 --version; command -v entire || true; command -v entire-cli || true","yield_time_ms":10000,"max_output_tokens":1000})
]); for (let i=0;i<results.length;i++){text(`--- ${i+1} ---`);text(results[i].status==="fulfilled"?results[i].value.output:String(results[i].reason));}

